        # search the users
        return db.execute("select * from users where name like ? limit 50", ("%" + q + "%",)).fetchall()
    except:
        return []

def find_users_by_domain(db, domain):
    if not isinstance(domain, str) or not domain or "@" in domain or any(c.isspace() for c in domain):
        raise ValueError(f"invalid email domain: {domain!r}")
    # Escape LIKE wildcards so a domain containing % or _ matches literally,
    # not as a pattern (e.g. "a_b.com" must not match "axb.com").
    escaped_domain = (
        domain.replace(LIKE_ESCAPE_CHAR, LIKE_ESCAPE_CHAR * 2)
        .replace("%", LIKE_ESCAPE_CHAR + "%")
        .replace("_", LIKE_ESCAPE_CHAR + "_")
    )
    try:
        return db.execute(
            "select * from users where email like ? escape ? limit ?",
            ("%@" + escaped_domain, LIKE_ESCAPE_CHAR, PAGE_SIZE),
        ).fetchall()
    except sqlite3.Error as err:
        logger.error("find_users_by_domain failed: domain=%r error=%s", domain, err)
        return []
